class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        import bisect
        A, B = [], []
        i = s.find(a)
        while i != -1:
            A.append(i)
            i = s.find(a, i + 1)
        i = s.find(b)
        while i != -1:
            B.append(i)
            i = s.find(b, i + 1)
        res = []
        for i in A:
            p = bisect.bisect_left(B, i - k)
            if p < len(B) and B[p] <= i + k:
                res.append(i)
        return res

