class Solution {
public:
    vector<int> beautifulIndices(string s, string a, string b, int k) {
        vector<int> A, B, res;
        for (size_t p = s.find(a); p != string::npos; p = s.find(a, p + 1)) A.push_back(p);
        for (size_t p = s.find(b); p != string::npos; p = s.find(b, p + 1)) B.push_back(p);
        for (int i : A) {
            auto it = lower_bound(B.begin(), B.end(), i - k);
            if (it != B.end() && *it <= i + k) res.push_back(i);
        }
        return res;
    }
};

