class Solution {
    public List<Integer> beautifulIndices(String s, String a, String b, int k) {
        List<Integer> A = new ArrayList<>(), B = new ArrayList<>();
        for (int i = s.indexOf(a); i != -1; i = s.indexOf(a, i + 1)) A.add(i);
        for (int i = s.indexOf(b); i != -1; i = s.indexOf(b, i + 1)) B.add(i);
        List<Integer> res = new ArrayList<>();
        for (int i : A) {
            int p = Collections.binarySearch(B, i - k);
            if (p < 0) p = -p - 1;
            if (p < B.size() && B.get(p) <= i + k) res.add(i);
        }
        return res;
    }
}

