var beautifulIndices = function(s, a, b, k) {
    const A = [], B = [];
    for (let i = s.indexOf(a); i !== -1; i = s.indexOf(a, i + 1)) A.push(i);
    for (let i = s.indexOf(b); i !== -1; i = s.indexOf(b, i + 1)) B.push(i);
    const res = [];
    for (const i of A) {
        let lo = 0, hi = B.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (B[mid] < i - k) lo = mid + 1; else hi = mid;
        }
        if (lo < B.length && B[lo] <= i + k) res.push(i);
    }
    return res;
};

